---@param name string
---@param args integer[]
---@return table<string, any>?
local function decodeEvent(name, args)
  if name == "CEventNetworkEntityDamage" then
    local layout = DAMAGE[#args]
    if not layout then return nil end
    local e = decode(layout, args)
    if not e.victim then return nil end
    if e.incapacitated == nil then e.incapacitated = false end
    if e.enduranceDamage == nil then e.enduranceDamage = 0.0 end
    return e
  end
  local layout = LAYOUTS[name]
  if not layout then return nil end
  return decode(layout, args)
end

