---@param filter? fun(e: table<string, any>): boolean
---@return fun(fn: fun(e: table)): fun()
local function onDecoded(name, label, filter)
  return function(fn)
    K.checkFn(label, fn)
    ---@param event string
    ---@param args integer[]
    return K.listen("gameEventTriggered", function(event, args)
