---@param name string
---@param fn fun(e: fx.GameEvent.Ai)
---@return fun() off
G.onAiEvent = function(name, fn)
  if type(name) ~= "string" or name == "" then error("fx.Events.Game.onAiEvent: name must be an event name", 2) end
  K.checkFn("Game.onAiEvent", fn)
  ---@param entities any
  ---@param entity any
  ---@param data any
  return K.listen(name, function(entities, entity, data)
    local list = {}
    for _, h in ipairs(K.tbl(entities)) do
      local e = K.entity(h)
      if e then list[#list + 1] = e end
    end
    data = K.tbl(data)
    local xyz = type(data[1]) == "table" and data[1] or data
    local position = type(xyz[1]) == "number" and #xyz >= 3 and K.vec(xyz[1], xyz[2], xyz[3]) or nil
    K.call("Game.onAiEvent", fn, { name = name, entities = list, entity = K.entity(entity), position = position, data = data })
  end)
end

